import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"6、【讼】 坎下乾上","description":"周易尚氏学 - 6、【讼】 坎下乾上","frontmatter":{"title":"6、【讼】 坎下乾上","description":"周易尚氏学 - 6、【讼】 坎下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/011.md","filePath":"zh/classics/shangshi/011.md"}'),h={name:"zh/classics/shangshi/011.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_6、【讼】-坎下乾上" tabindex="-1">6、【讼】 坎下乾上 <a class="header-anchor" href="#_6、【讼】-坎下乾上" aria-label="Permalink to “6、【讼】 坎下乾上”">​</a></h1><p>乾阳上升。坎水下降。乃乾即在上。坎即在下。违行。气不交。故曰讼。二阳居阴中。故有孚。坎中实。故窒。坎忧故惕。二虽不当位。居中。故吉。二无应。遇敌。故终凶。九五中正。故利见大人。坤为大川。二入之不当位。无应与。不能出。(若解则能出)沈沦于坤水之中。故曰不利涉大川。</p><p>彖曰。讼上刚下险。险而健讼。讼有孚窒惕。中吉。刚来而得中也。终凶。讼不可成也。利见大人。尚中正也。不利涉大川。入于渊也。</p><p>刚来得中谓二也。中正谓五也。坤为渊。易林震之复云。藏匿渊底。言复阳居坤下。故曰藏匿渊底。是以坤为渊也。今二入居坤中。故曰入于渊。而上无应不能出。沈溺渊中。故曰不利。</p><p>象曰。天与水违行。讼。君子以作事谋始。</p><p>需水上乾下。故气交。反之则背道而驰。愈去愈远。故曰违行。行道也。违行言异道而行也。坎为谋。坤为事。二居坤中。故曰作事。二无应。故入不能出。若慎始则免矣。卦气以下为始。王弼云。凡讼之起。契之不明。孔疏由于初时契要之过。慎始制契。则讼端绝。按乾坎皆为信。契要者信也。王注优于各家。</p><p>初六。不永所事。小有言。终吉。</p><p>事。讼事也。讼始于初。然初有应。初四相上下成中孚。各当位。则讼事息矣。故曰不永所事。坎上下兑口相背。故有言。有言即讼也。不永故曰小有言。有应故终吉。</p><h3 id="象曰。不永所事。讼不可长也。虽小有言。其辩明也。" tabindex="-1">象曰。不永所事。讼不可长也。虽小有言。其辩明也。 <a class="header-anchor" href="#象曰。不永所事。讼不可长也。虽小有言。其辩明也。" aria-label="Permalink to “象曰。不永所事。讼不可长也。虽小有言。其辩明也。”">​</a></h3><p>兑口多。故曰辩明。</p><p>九二。不克讼。归而逋。其邑人三百户。无眚。</p><p>坎为隐伏。故曰逋。上无应。故不克讼。不克讼故逋。逋逃也。逃归何处乎。二居坤中。坤为邑为百为户。茹敦和曰。坎数三。故曰其邑人三百户。言二选于坤邑之中也。坎为眚。二逋坤中。孚于上下。故无眚。眚。释文马云灾也。</p><h3 id="象曰。不克讼。归逋窜也。自下讼上。患至掇也。" tabindex="-1">象曰。不克讼。归逋窜也。自下讼上。患至掇也。 <a class="header-anchor" href="#象曰。不克讼。归逋窜也。自下讼上。患至掇也。" aria-label="Permalink to “象曰。不克讼。归逋窜也。自下讼上。患至掇也。”">​</a></h3><p>上谓五。五刚。二与为敌。故曰自下讼上。吴先生曰。掇。借为辍。止也。愚按集韵掇音辍读若朵。逸周书曰。绵绵不绝。蔓蔓若何。毫末不掇。将成斧柯。不掇即不辍。言毫末虽微。长而不止。即成斧柯。然则掇辍古通用。又河北方言谓人避事曰掇避。正与此同。掇或作躲。玉篇身也。无避匿之义。非也。归而逋。即辍讼矣。辍之故因不克讼而有患也。释文郑作惙。忧也。近师俞樾又作缀。言祸患之来。联缀不已也。但小象原以释经文。作惙作缀于逋义皆无涉。若作辍。则正释逋义也。逋而辍讼。讼止故无眚。</p><p>六三。食旧德。贞厉。终吉。或从王事。无成。</p><p>乾为旧为德。坎为食。三承重阳。故曰食旧德。失位故贞厉。承阳有应故终吉。三承乾。乾为王。故曰从王事。坤柔故无成。义详坤六三前释。</p><h3 id="象曰。食旧德。从上吉也。" tabindex="-1">象曰。食旧德。从上吉也。 <a class="header-anchor" href="#象曰。食旧德。从上吉也。" aria-label="Permalink to “象曰。食旧德。从上吉也。”">​</a></h3><p>从上即承乾。</p><p>九四。不克讼。复即命。渝。安贞。吉。</p><p>阳遇阳则窒。故不克讼。巽为命。即。就也。安也。初有应。言复初而安命也。渝变也。讼则争。争则不安。不讼则变而为安贞矣。故吉也。</p><h3 id="象曰。复即命。渝安贞吉。不失也。" tabindex="-1">象曰。复即命。渝安贞吉。不失也。 <a class="header-anchor" href="#象曰。复即命。渝安贞吉。不失也。" aria-label="Permalink to “象曰。复即命。渝安贞吉。不失也。”">​</a></h3><p>失与轶通。荀子哀公篇。其马将失。即其马将轶也。轶突也。过也。左传隐九年。惧其侵轶我也。说文车相出也。即从后出前也。不轶即不前出也。释安贞之义也。与随初。比二。小畜初。同。</p><p>九五。讼元吉。</p><p>五位极尊。故曰元。五中正。故讼吉。</p><h3 id="象曰。讼元吉。以中正也。" tabindex="-1">象曰。讼元吉。以中正也。 <a class="header-anchor" href="#象曰。讼元吉。以中正也。" aria-label="Permalink to “象曰。讼元吉。以中正也。”">​</a></h3><p>有中而不正者。有正而不中者。中且正。无不吉。</p><p>上九。或锡之韖带。终朝三褫之。</p><p>说文韖大带也。锡命也。上应三。三巽为带。乾大故曰韖带。乃巽为陨落。故终朝三褫之。褫夺也。坤为夜。乾为朝。上居乾终。故曰终朝。与乾三终日同义。上应三。三体离。离卦数三。(此数失传。祇易林洞林邵子用之)故曰三褫。先儒不知巽为陨落。(象本左氏。后祇易林用之)褫之故。全在巽。故无得解者。岂知中孚初九云。有它不燕。以应四巽也。姤九四。包无鱼。鼎九四。鼎折足。大过九四。有它吝。皆以应初巽也。例甚明也。释文褫郑本作扦。惠氏栋据淮南人间训。盗扦其衣被。高诱注云。扦夺也。是仍与褫同。乃宋项安世周易玩辞。引郑注曰。三扦。三加之也。后杨慎臧琳朱芹等。颇祖述其说。谓三扦其绅。以为夸耀。故象曰不足敬。但论语之拖绅。因孔子病卧。君来视。故加绅于朝服。以为敬。今非病卧。曰束绅垂绅皆可。曰拖绅。似不合也。</p><h3 id="象曰。以讼受服。亦不足敬也。" tabindex="-1">象曰。以讼受服。亦不足敬也。 <a class="header-anchor" href="#象曰。以讼受服。亦不足敬也。" aria-label="Permalink to “象曰。以讼受服。亦不足敬也。”">​</a></h3><p>乾为敬。旋得旋失。故不足敬。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
